Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastReader fr = new FastReader();
        long w = fr.nextLong();
        long m = fr.nextLong();

        if (canBalance(w, m)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    static boolean canBalance(long w, long m) {
        if (w <= 3 || m == 1) return true;

        for (long offset = -1; offset <= 1; offset++) {
            long adjustedM = m + offset;
            if (adjustedM % w == 0 && canBalance(w, adjustedM / w)) {
                return true;
            }
        }
        return false;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}
